/**
 * Query string of PUT /roots/:root_id/content (small write, body at most 4 MiB). device_name may also come from the X-Allternit-Device-Name header.
 */
export interface SmallWriteQuery {
  parent_id: ItemId;
  name: string;
  /** Required when replacing an existing file. */
  base_rev?: Rev;
  /** Default keep_both. */
  on_conflict?: OnConflict;
  /** Used to name a conflict copy. */
  device_name?: string;
  /** As in UploadCreateRequest. */
  utc_offset_minutes?: number;
}

/**
 * Decided (Eoj 2026-11-15): v2 writes none, i.e. plain file names in the user's own R2 bucket, the same trust class as files they upload. files_key_v1 is reserved, not used in v2: XChaCha20-Poly1305 with the snapshot subkey of the user's Files root key (keys.json).
 */
export type SnapshotEncryption = "none" | "files_key_v1";
export const SNAPSHOT_ENCRYPTION_VALUES: readonly SnapshotEncryption[] = ["none", "files_key_v1"];

export interface SnapshotItem {
  id: ItemId;
  parent_id?: ItemId;
  name: string;
  kind: ItemKind;
  size: number;
  rev: Rev;
  modified_at: Timestamp;
  root_link?: RootId;
}

/**
 * R2 key: files-snapshots/<computer_id>/v1/manifest.json
 */
export interface SnapshotManifest {
  schema: "files-snapshot/1";
  computer_id: ComputerId;
  written_at: Timestamp;
  encryption: SnapshotEncryption;
  /** v2 writers always write false (Eoj 2026-11-15: plain names). true is reserved, not used in v2: names would live only in ciphertext, with encryption files_key_v1 and key_id set. A v2 reader that meets true shows the folder as "names unavailable" instead of failing. */
  names_encrypted: boolean;
  /** names_encrypted false only. */
  roots?: Root[];
  /** Reserved, not used in v2. names_encrypted true: base64url XChaCha20-Poly1305 of the roots JSON array. */
  ciphertext?: string;
  /** Reserved, not used in v2. base64url 24-byte nonce. */
  nonce?: string;
  /** Reserved, not used in v2. Key reference: the FilesKeyInfo.key_id whose snapshot subkey (HKDF info "files-snapshot/1") sealed this file. */
  key_id?: string;
}

/**
 * R2 key: files-snapshots/<computer_id>/v1/roots/<root_id>.json
 */
export interface SnapshotRootFile {
  schema: "files-snapshot-root/1";
  root_id: RootId;
  cursor: Cursor;
  written_at: Timestamp;
  encryption: SnapshotEncryption;
  /** v2 writers always write false (Eoj 2026-11-15: plain names). true is reserved, not used in v2: names would live only in ciphertext, with encryption files_key_v1 and key_id set. A v2 reader that meets true shows the folder as "names unavailable" instead of failing. */
  names_encrypted: boolean;
  /** names_encrypted false only. */
  items?: SnapshotItem[];
  /** Reserved, not used in v2. names_encrypted true: base64url XChaCha20-Poly1305 of the items JSON array. */
  ciphertext?: string;
  /** Reserved, not used in v2. base64url 24-byte nonce. */
  nonce?: string;
  /** Reserved, not used in v2. Key reference: the FilesKeyInfo.key_id whose snapshot subkey (HKDF info "files-snapshot/1") sealed this file. */
  key_id?: string;
}

