/**
 * UTC time, RFC 3339 with Z.
 */
export type Timestamp = string;

export interface TransportCandidate {
  kind: TransportKind;
  /** loopback/mesh: URL prefix ending in /api/v1/files/v2. relay: the proxy URL; the client sends {method, path: "/api/v1/files/v2/...", headers, body, body_encoding} to it. gateway: https://api.allternit.com/api/v1/files-gateway. */
  base_url: string;
  /** Lower tries first. */
  priority: number;
  /** Largest request body this transport takes, in decoded bytes. relay = 5242880 (runtime_relay.rs MAX_RELAY_BODY_BYTES; base64 bodies are measured as len*3/4). Chunks are at most 4194304, so one chunk always fits. */
  max_request_bytes: number;
}

/**
 * loopback = same machine (Desktop app to its own runtime). mesh = Headscale/tsnet, only between the user's own devices. relay = cloud-api POST /api/v1/runtime-devices/:id/proxy (RelayRequest envelope; the Files path goes in `path`); the baseline that always exists. gateway = cloud-api Files gateway for guests holding a share capability token.
 */
export type TransportKind = "loopback" | "mesh" | "relay" | "gateway";
export const TRANSPORT_KIND_VALUES: readonly TransportKind[] = ["loopback", "mesh", "relay", "gateway"];

